import itertools, random
from collections import deque

def girth(graph, n):
    """Compute girth of graph. Return infinity if no cycles."""
    INF = float('inf')
    min_cycle = INF

    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        q = deque([start])
        while q and min_cycle > 0:
            u = q.popleft()
            for v in graph[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v and parent[v] != u:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
        if min_cycle == 3:
            break

    return min_cycle if min_cycle != INF else None

def is_colorable(graph, n, k):
    """Check if graph is k-colorable using backtracking."""
    colors = [-1] * n

    def can_color(v):
        if v == n:
            return True
        for c in range(k):
            ok = True
            for u in graph[v]:
                if colors[u] == c:
                    ok = False
                    break
            if ok:
                colors[v] = c
                if can_color(v+1):
                    return True
                colors[v] = -1
        return False

    return can_color(0)

