def greedy_build(seed):
    n = 25
    graph = [[] for _ in range(n)]
    edges = []

    # Start with cycle
    for i in range(n):
        j = (i+1) % n
        graph[i].append(j)
        graph[j].append(i)
        if i < j:
            edges.append((i,j))

    chords = []
    for i in range(n):
        for j in range(i+2, n):
            if j != i+1 and not (i == 0 and j == n-1):
                chords.append((i,j))

    random.seed(seed)
    random.shuffle(chords)

    for (u,v) in chords:
        graph[u].append(v)
        graph[v].append(u)
        g = girth(graph, n)
        if g is None or g >= 7:
            edges.append((u,v) if u < v else (v,u))
        else:
            graph[u].remove(v)
            graph[v].remove(u)

    return graph, edges

